#!/usr/bin/env python3
"""SVE2 (VL=256) emitter for x265 pixel SAD (16x16/32x32), upstream-exact
vs x265_pixel_sad_*_neon_dotprod.

Simple sum-of-absolute-differences; expected to show no optimization space
on SVE256 for 16-wide rows (width under-utilization vs NEON), covered for
completeness (docs/37). Per row: 2 ld1b + abd + uaddv.
"""

import argparse


def emit(func_name, n):
    return """\
// Generated by tools/emit_sad_sve2_shared.py -- do not edit.
// SAD %(n)dx%(n)d (SVE2, VL=256).
#include <arm_sve.h>

extern "C" int %(func_name)s(const uint8_t* a, intptr_t sa,
                             const uint8_t* b, intptr_t sb)
{
    const svbool_t p = svwhilelt_b8((uint32_t)0, (uint32_t)%(n)d);
    uint64_t total = 0;
    for (int r = 0; r < %(n)d; r++)
    {
        svuint8_t x = svld1_u8(p, a + r * sa);
        svuint8_t y = svld1_u8(p, b + r * sb);
        svuint8_t d = svabd_u8_x(p, x, y);
        total += svaddv_u8(p, d);
    }
    return (int)total;
}
""" % {"func_name": func_name, "n": n}


def emit_16x16(func_name="dynopt_sad_16x16_sve2"):
    return emit(func_name, 16)


def emit_32x32(func_name="dynopt_sad_32x32_sve2"):
    return emit(func_name, 32)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("out")
    ap.add_argument("--n", type=int, choices=(16, 32), default=16)
    args = ap.parse_args()
    with open(args.out, "w") as f:
        f.write(emit_16x16() if args.n == 16 else emit_32x32())
    print("wrote %s" % args.out)


if __name__ == "__main__":
    main()
